import { useCallback, useEffect, useRef, useState } from 'react';
import './index.css';
import type { AppData, Generation, TemplateId, View } from './lib/types';
import { useStore, uid } from './lib/store';
import { askAI } from './lib/ai';
import { buildPrompt, copyText, systemFor } from './lib/prompts';
import { TEMPLATES, templateOf } from './data/templates';
import Sidebar, { BusinessDialog } from './components/Sidebar';
import Composer, { TemplatePicker } from './components/Composer';
import ResultPanel, { type Pending } from './components/ResultPanel';
import History from './components/History';
import Chat from './components/Chat';
import { Toast, type ToastData } from './components/ui';

export default function App() {
  const store = useStore();
  const { data } = store;
  const [view, setView] = useState<View>('escribir');
  const [pending, setPending] = useState<Pending | null>(null);
  const [toast, setToast] = useState<ToastData>(null);
  const [editingBusiness, setEditingBusiness] = useState(false);
  const timer = useRef<number>();
  const lastRun = useRef<() => void>(() => {});
  const resultRef = useRef<HTMLDivElement>(null);

  const notify = useCallback((message: string, action?: { label: string; run: () => void }) => {
    window.clearTimeout(timer.current);
    setToast({ message, action });
    timer.current = window.setTimeout(() => setToast(null), 4200);
  }, []);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  const { draft } = data;
  const tpl = templateOf(draft.templateId);
  const active = data.history.find(g => g.id === data.activeId);
  const shown = active && active.templateId === draft.templateId ? active : undefined;
  const busy = pending?.status === 'streaming';

  /** Genera un texto nuevo con los datos del formulario. */
  const generateNew = () => {
    const req = { templateId: draft.templateId, values: { ...draft.values[draft.templateId] }, tone: draft.tone, length: draft.length };
    const run = async () => {
      setPending({ kind: 'new', text: '', status: 'streaming' });
      if (window.innerWidth < 1024) window.setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 60);
      try {
        const text = await askAI(buildPrompt(req), { system: systemFor(data.business), maxTokens: 900,
          onToken: t => setPending(p => (p ? { ...p, text: t } : p)) });
        if (!text.trim()) throw new Error('La respuesta llegó vacía.');
        store.addGeneration({ ...req, id: uid('g'), variants: [text], active: 0, createdAt: Date.now(), favorite: false });
        setPending(null);
      } catch (e) {
        setPending(p => ({ kind: 'new', text: p?.text ?? '', status: 'error', error: e instanceof Error ? e.message : undefined }));
      }
    };
    lastRun.current = run;
    void run();
  };

  /** Pide una versión alternativa del texto abierto. */
  const generateVariant = (g: Generation) => {
    const run = async () => {
      setPending({ kind: 'variant', genId: g.id, text: '', status: 'streaming' });
      try {
        const text = await askAI(buildPrompt(g, g.variants), { system: systemFor(data.business), maxTokens: 900, temperature: 0.9,
          onToken: t => setPending(p => (p ? { ...p, text: t } : p)) });
        if (!text.trim()) throw new Error('La respuesta llegó vacía.');
        store.addVariant(g.id, text);
        setPending(null);
      } catch (e) {
        setPending(p => ({ kind: 'variant', genId: g.id, text: p?.text ?? '', status: 'error', error: e instanceof Error ? e.message : undefined }));
      }
    };
    lastRun.current = run;
    void run();
  };

  const selectTemplate = (id: TemplateId) => {
    if (busy) return;
    setPending(null);
    store.setDraft({ templateId: id, tone: id === draft.templateId ? draft.tone : templateOf(id).defaultTone });
  };

  const open = (g: Generation) => {
    if (busy) return;
    setPending(null);
    store.openGeneration(g);
    setView('escribir');
  };

  const copy = (text: string) => { void copyText(text); notify('Texto copiado al portapapeles'); };

  const remove = (g: Generation) => {
    const snapshot: AppData = data;
    store.removeGeneration(g.id);
    notify('Texto eliminado del historial', { label: 'Deshacer', run: () => store.replace(snapshot) });
  };

  const reset = () => {
    if (busy) return;
    const snapshot = data;
    setPending(null);
    store.reset();
    setView('escribir');
    notify('Datos de ejemplo restablecidos', { label: 'Deshacer', run: () => store.replace(snapshot) });
  };

  return (
    <div className="redacta min-h-screen bg-[#EEF0F3] text-[#161B26] lg:flex">
      <Sidebar view={view} onView={setView} historyCount={data.history.length} business={data.business}
        onBusiness={() => setEditingBusiness(true)} onReset={reset} />

      <main className={`min-w-0 flex-1 px-4 pt-5 sm:px-6 lg:px-8 lg:pt-6 ${view === 'chat' ? 'pb-0' : 'pb-20'}`}>
        {view === 'escribir' && (
          <div className="mx-auto max-w-[1180px]">
            <div className="flex flex-col gap-3">
              <h1 className="text-[22px] font-bold leading-tight tracking-[-0.01em] sm:text-[24px]">¿Qué escribimos hoy?</h1>
              <TemplatePicker value={draft.templateId} onChange={selectTemplate} />
            </div>
            <div className="mt-5 grid items-start gap-5 lg:grid-cols-[minmax(320px,380px)_minmax(0,1fr)]">
              <Composer
                key={draft.templateId}
                draft={draft}
                busy={busy}
                onField={store.setField}
                onTone={tone => store.setDraft({ tone })}
                onLength={length => store.setDraft({ length })}
                onExample={() => store.setDraft({ values: { ...draft.values, [draft.templateId]: { ...tpl.example } } })}
                onClear={() => store.setDraft({ values: { ...draft.values, [draft.templateId]: Object.fromEntries(tpl.fields.filter(f => f.type === 'select').map(f => [f.key, f.options![0]])) } })}
                onGenerate={generateNew}
              />
              <div ref={resultRef} className="min-w-0 scroll-mt-28 lg:sticky lg:top-6">
                <ResultPanel
                  templateId={draft.templateId}
                  draftMeta={{ values: draft.values[draft.templateId] ?? {}, tone: draft.tone, length: draft.length }}
                  gen={shown}
                  pending={pending}
                  recent={data.history.filter(g => g.templateId === draft.templateId)}
                  onSelect={i => shown && store.updateGeneration(shown.id, { active: i })}
                  onCopy={copy}
                  onVariant={() => shown && generateVariant(shown)}
                  onSaveEdit={(i, text) => { if (shown) { store.editVariant(shown.id, i, text); notify('Cambios guardados'); } }}
                  onFavorite={() => shown && store.updateGeneration(shown.id, { favorite: !shown.favorite })}
                  onRetry={() => lastRun.current()}
                  onOpen={open}
                />
              </div>
            </div>
          </div>
        )}

        {view === 'historial' && (
          <History history={data.history} onOpen={open} onCopy={copy} onDelete={remove}
            onFavorite={g => store.updateGeneration(g.id, { favorite: !g.favorite })}
            onNew={() => { store.setDraft({ templateId: TEMPLATES[0].id }); setView('escribir'); }} />
        )}

        {view === 'chat' && (
          <Chat messages={data.chat} business={data.business} onAdd={store.addMessage} onCopy={copy}
            onClear={() => { const s = data; store.clearChat(); notify('Conversación borrada', { label: 'Deshacer', run: () => store.replace(s) }); }} />
        )}
      </main>

      {editingBusiness && (
        <BusinessDialog business={data.business} onClose={() => setEditingBusiness(false)}
          onSave={b => { store.setBusiness(b); setEditingBusiness(false); notify('Perfil del negocio guardado'); }} />
      )}
      <Toast toast={toast} onClose={() => setToast(null)} />
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import { ArrowUp, Copy, Feather, MessagesSquare, Plus } from 'lucide-react';
import type { Business, ChatMessage } from '../lib/types';
import { chatAI } from '../lib/ai';
import { chatSystemFor } from '../lib/prompts';
import { uid } from '../lib/store';
import { Button, ErrorBox, RichText } from './ui';

const SUGGESTIONS = [
  'Ideas para el cartel de la pizarra de esta semana',
  'Cómo responder a un cliente que pide un descuento',
  'Cinco ganchos para un reel enseñando el obrador',
  'Revisa este texto y hazlo más claro: ',
];

type Props = { messages: ChatMessage[]; business: Business; onAdd: (m: ChatMessage) => void; onClear: () => void; onCopy: (t: string) => void };

export default function Chat({ messages, business, onAdd, onClear, onCopy }: Props) {
  const [input, setInput] = useState('');
  const [streaming, setStreaming] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const scroller = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const el = scroller.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [messages.length, streaming, error]);

  useEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = Math.min(el.scrollHeight, 180) + 'px';
  }, [input]);

  const ask = async (history: ChatMessage[]) => {
    setError(null);
    setStreaming('');
    try {
      const text = await chatAI(history.slice(-12).map(m => ({ role: m.role, content: m.content })), {
        system: chatSystemFor(business), onToken: t => setStreaming(t), maxTokens: 1200,
      });
      if (!text.trim()) throw new Error('La respuesta llegó vacía.');
      onAdd({ id: uid('c'), role: 'assistant', content: text, createdAt: Date.now() });
    } catch (e) {
      setError(e instanceof Error ? e.message : 'La IA no está disponible en este momento.');
    } finally {
      setStreaming(null);
    }
  };

  const send = (raw: string) => {
    const content = raw.trim();
    if (!content || streaming !== null) return;
    const msg: ChatMessage = { id: uid('c'), role: 'user', content, createdAt: Date.now() };
    onAdd(msg);
    setInput('');
    void ask([...messages, msg]);
  };

  const pick = (s: string) => {
    if (s.endsWith(': ')) { setInput(s); inputRef.current?.focus(); return; }
    send(s);
  };

  const busy = streaming !== null;

  return (
    <div className="mx-auto flex h-[calc(100dvh-118px)] max-w-[820px] flex-col lg:h-[calc(100vh-24px)]">
      <div className="flex items-center justify-between gap-3 pb-4">
        <div className="min-w-0">
          <h1 className="text-[22px] font-bold tracking-[-0.01em] sm:text-[24px]">Chat libre</h1>
          <p className="mt-0.5 truncate text-[13.5px] text-[#5A6372]">Pide ideas, revisiones o lo que no encaje en una plantilla. Conoce {business.name}.</p>
        </div>
        {messages.length > 0 && <Button onClick={onClear} disabled={busy} className="shrink-0"><Plus size={15} aria-hidden /> <span className="hidden sm:inline">Nueva conversación</span><span className="sm:hidden">Nueva</span></Button>}
      </div>

      <div ref={scroller} className="scroll-thin flex-1 overflow-y-auto rounded-2xl border border-[#E1E4E9] bg-white px-4 py-5 sm:px-7">
        {messages.length === 0 && !busy ? (
          <div className="flex h-full flex-col items-center justify-center py-8 text-center">
            <span className="grid h-11 w-11 place-items-center rounded-xl bg-[#EAEEFC] text-[#2A4BD7]"><MessagesSquare size={20} aria-hidden /></span>
            <p className="mt-4 text-[17px] font-semibold">¿En qué te ayudo hoy?</p>
            <p className="mt-1 max-w-[380px] text-[14px] text-[#5A6372]">Escribe tu pregunta o empieza por una de estas ideas.</p>
            <div className="mt-5 grid w-full max-w-[560px] gap-2 sm:grid-cols-2">
              {SUGGESTIONS.map(s => (
                <button key={s} onClick={() => pick(s)} className="rounded-xl border border-[#E1E4E9] px-3.5 py-3 text-left text-[13.5px] leading-snug hover:border-[#9AA2AE] hover:bg-[#F8F9FB]">
                  {s.replace(/: $/, '…')}
                </button>
              ))}
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            {messages.map(m => <Bubble key={m.id} m={m} onCopy={onCopy} />)}
            {busy && (
              <div className="flex gap-3" aria-live="polite">
                <Avatar />
                <div className="min-w-0 flex-1 pt-1">
                  {streaming
                    ? <RichText text={streaming} streaming className="text-[15px] leading-[1.65]" />
                    : <p className="caret text-[14px] text-[#5A6372]">Pensando</p>}
                </div>
              </div>
            )}
            {error && <ErrorBox message={error} onRetry={() => void ask(messages)} />}
          </div>
        )}
      </div>

      {messages.length > 0 && (
        <div className="no-scrollbar -mx-4 flex gap-1.5 overflow-x-auto px-4 pt-3 sm:mx-0 sm:px-0">
          {SUGGESTIONS.map(s => (
            <button key={s} onClick={() => pick(s)} disabled={busy}
              className="shrink-0 rounded-full border border-[#D5D9E0] bg-white px-3 py-1.5 text-[12.5px] text-[#3C4452] hover:border-[#9AA2AE] disabled:opacity-50">
              {s.replace(/: $/, '…')}
            </button>
          ))}
        </div>
      )}

      <form onSubmit={e => { e.preventDefault(); send(input); }} className="mt-3 flex items-end gap-2 rounded-2xl border border-[#D5D9E0] bg-white p-2 pl-4 focus-within:border-[#2A4BD7] focus-within:shadow-[0_0_0_3px_rgba(42,75,215,.14)]">
        <textarea ref={inputRef} rows={1} value={input} onChange={e => setInput(e.target.value)} aria-label="Mensaje"
          onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(input); } }}
          placeholder="Escribe tu mensaje…" className="max-h-[180px] flex-1 resize-none bg-transparent py-2 text-[15px] leading-snug text-[#161B26] outline-none placeholder:text-[#8A92A0]" />
        <button type="submit" disabled={!input.trim() || busy} title="Enviar mensaje"
          className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#2A4BD7] text-white transition hover:bg-[#2340BC] disabled:bg-[#C9CFDA]">
          <ArrowUp size={18} aria-hidden />
        </button>
      </form>
      <p className="pb-12 pt-2 text-[12px] text-[#8A92A0] lg:pb-10">Enter para enviar · Mayús + Enter para una línea nueva</p>
    </div>
  );
}

function Avatar() {
  return <span className="grid h-8 w-8 shrink-0 place-items-center rounded-[9px] bg-[#161B26] text-white"><Feather size={15} aria-hidden /></span>;
}

function Bubble({ m, onCopy }: { m: ChatMessage; onCopy: (t: string) => void }) {
  if (m.role === 'user') {
    return (
      <div className="flex justify-end">
        <p className="max-w-[85%] whitespace-pre-wrap rounded-2xl rounded-br-md bg-[#EAEEFC] px-4 py-2.5 text-[15px] leading-snug text-[#161B26]">{m.content}</p>
      </div>
    );
  }
  return (
    <div className="group flex gap-3">
      <Avatar />
      <div className="min-w-0 flex-1 pt-1">
        <RichText text={m.content} className="text-[15px] leading-[1.65] text-[#161B26]" />
        <button onClick={() => onCopy(m.content)} className={clsx('mt-2 inline-flex items-center gap-1.5 rounded-lg px-2 py-1 text-[12.5px] font-medium text-[#5A6372] hover:bg-[#EEF0F3] hover:text-[#161B26]')}>
          <Copy size={13} aria-hidden /> Copiar respuesta
        </button>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import { Eraser, WandSparkles } from 'lucide-react';
import type { Draft, Length, TemplateId, Tone } from '../lib/types';
import { LENGTHS, TONES } from '../lib/types';
import { TEMPLATES, templateOf } from '../data/templates';
import { Button, ICONS } from './ui';

export function TemplatePicker({ value, onChange }: { value: TemplateId; onChange: (id: TemplateId) => void }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const box = ref.current;
    const el = box?.querySelector<HTMLElement>('[aria-selected="true"]');
    if (box && el && box.scrollWidth > box.clientWidth) box.scrollTo({ left: el.offsetLeft - 16, behavior: 'smooth' });
  }, [value]);
  return (
    <div ref={ref} role="tablist" aria-label="Plantillas" className="no-scrollbar relative -mx-4 flex gap-2 overflow-x-auto px-4 sm:mx-0 sm:px-0">
      {TEMPLATES.map(t => {
        const Icon = ICONS[t.id];
        const on = t.id === value;
        return (
          <button key={t.id} role="tab" aria-selected={on} onClick={() => onChange(t.id)}
            className={clsx('flex shrink-0 items-center gap-2 rounded-full border px-3.5 py-2 text-[13.5px] font-medium transition',
              on ? 'border-[#161B26] bg-[#161B26] text-white' : 'border-[#D5D9E0] bg-white text-[#3C4452] hover:border-[#9AA2AE]')}>
            <Icon size={15} aria-hidden /> {t.name}
          </button>
        );
      })}
    </div>
  );
}

type Props = {
  draft: Draft;
  busy: boolean;
  onField: (key: string, value: string) => void;
  onTone: (t: Tone) => void;
  onLength: (l: Length) => void;
  onExample: () => void;
  onClear: () => void;
  onGenerate: () => void;
};

export default function Composer({ draft, busy, onField, onTone, onLength, onExample, onClear, onGenerate }: Props) {
  const t = templateOf(draft.templateId);
  const values = draft.values[draft.templateId] ?? {};
  const [errors, setErrors] = useState<Record<string, string>>({});
  const empty = t.fields.every(f => f.type === 'select' || !values[f.key]?.trim());

  const submit = () => {
    const next: Record<string, string> = {};
    t.fields.forEach(f => { if (f.required && !values[f.key]?.trim()) next[f.key] = 'Este dato hace falta para escribir el texto.'; });
    setErrors(next);
    if (Object.keys(next).length === 0) onGenerate();
  };

  return (
    <form onSubmit={e => { e.preventDefault(); submit(); }}
      onKeyDown={e => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); submit(); } }}
      className="flex flex-col rounded-2xl border border-[#E1E4E9] bg-white lg:sticky lg:top-6 lg:h-[calc(100vh-150px)] lg:min-h-[520px]">
      <div className="scroll-thin flex-1 overflow-y-auto p-4 sm:p-5">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <h2 className="text-[16px] font-bold leading-tight">{t.name}</h2>
          <p className="mt-1 text-[13px] leading-snug text-[#5A6372]">{t.description}</p>
        </div>
        {empty
          ? <Button variant="ghost" onClick={onExample} className="-mr-1 -mt-1 shrink-0 text-[#2A4BD7]">Usar ejemplo</Button>
          : <Button variant="ghost" onClick={() => { onClear(); setErrors({}); }} className="-mr-1 -mt-1 shrink-0" title="Vaciar campos"><Eraser size={14} aria-hidden /> Vaciar</Button>}
      </div>

      <div className="mt-4 space-y-3.5">
        {t.fields.map(f => {
          const id = `f-${t.id}-${f.key}`;
          const common = {
            id, value: values[f.key] ?? '', 'aria-invalid': !!errors[f.key],
            className: clsx('field', errors[f.key] && 'invalid'),
          };
          const change = (v: string) => { onField(f.key, v); if (errors[f.key]) setErrors({ ...errors, [f.key]: '' }); };
          return (
            <div key={f.key}>
              <label htmlFor={id} className="mb-1.5 flex items-baseline justify-between text-[13px] font-semibold text-[#161B26]">
                {f.label}
                {!f.required && f.type !== 'select' && <span className="text-[12px] font-normal text-[#8A92A0]">Opcional</span>}
              </label>
              {f.type === 'textarea' && <textarea {...common} rows={3} placeholder={f.placeholder} onChange={e => change(e.target.value)} className={clsx(common.className, 'resize-none')} />}
              {f.type === 'text' && <input {...common} placeholder={f.placeholder} onChange={e => change(e.target.value)} />}
              {f.type === 'select' && (
                <select {...common} onChange={e => change(e.target.value)}>
                  {f.options!.map(o => <option key={o}>{o}</option>)}
                </select>
              )}
              {errors[f.key] && <p className="mt-1 text-[12.5px] font-medium text-[#C2392F]">{errors[f.key]}</p>}
            </div>
          );
        })}
      </div>

      <fieldset className="mt-5">
        <legend className="mb-2 text-[13px] font-semibold">Tono</legend>
        <div className="flex flex-wrap gap-1.5">
          {TONES.map(tone => (
            <button key={tone} type="button" onClick={() => onTone(tone)} aria-pressed={draft.tone === tone}
              className={clsx('rounded-lg border px-2.5 py-1.5 text-[13px] font-medium transition',
                draft.tone === tone ? 'border-[#2A4BD7] bg-[#EAEEFC] text-[#1E37A3]' : 'border-[#E1E4E9] text-[#3C4452] hover:border-[#BCC2CC]')}>
              {tone}
            </button>
          ))}
        </div>
      </fieldset>

      <fieldset className="mt-4">
        <legend className="mb-2 text-[13px] font-semibold">Longitud</legend>
        <div className="grid grid-cols-3 rounded-[10px] bg-[#EEF0F3] p-1">
          {LENGTHS.map(l => (
            <button key={l.id} type="button" onClick={() => onLength(l.id)} aria-pressed={draft.length === l.id}
              className={clsx('rounded-lg px-2 py-1.5 text-center transition',
                draft.length === l.id ? 'bg-white text-[#161B26] shadow-sm' : 'text-[#5A6372] hover:text-[#161B26]')}>
              <span className="block text-[13px] font-semibold">{l.id}</span>
              <span className="block text-[11.5px] text-[#5A6372]">{l.words}</span>
            </button>
          ))}
        </div>
      </fieldset>

      </div>
      <div className="border-t border-[#EEF0F3] p-4 sm:px-5">
        <Button type="submit" variant="primary" disabled={busy} className="w-full py-3 text-[14.5px]">
          <WandSparkles size={16} aria-hidden /> {busy ? 'Escribiendo…' : 'Generar texto'}
        </Button>
        <p className="mt-2 text-center text-[12px] text-[#8A92A0]">Ctrl + Enter para generar</p>
      </div>
    </form>
  );
}

import { useMemo, useState, type ReactNode } from 'react';
import clsx from 'clsx';
import { Copy, Search, Star, Trash2, X } from 'lucide-react';
import type { Generation, TemplateId } from '../lib/types';
import { relTime } from '../lib/prompts';
import { TEMPLATES, templateOf, titleOf } from '../data/templates';
import { Button, TemplateBadge } from './ui';

type Props = {
  history: Generation[];
  onOpen: (g: Generation) => void;
  onCopy: (text: string) => void;
  onDelete: (g: Generation) => void;
  onFavorite: (g: Generation) => void;
  onNew: () => void;
};

export default function History({ history, onOpen, onCopy, onDelete, onFavorite, onNew }: Props) {
  const [q, setQ] = useState('');
  const [type, setType] = useState<TemplateId | 'todas'>('todas');
  const [favs, setFavs] = useState(false);

  const list = useMemo(() => {
    const s = q.trim().toLowerCase();
    return history.filter(g =>
      (type === 'todas' || g.templateId === type) && (!favs || g.favorite) &&
      (!s || [...g.variants, ...Object.values(g.values)].some(x => x.toLowerCase().includes(s))));
  }, [history, q, type, favs]);

  const counts = useMemo(() => {
    const c: Record<string, number> = {};
    history.forEach(g => { c[g.templateId] = (c[g.templateId] ?? 0) + 1; });
    return c;
  }, [history]);

  const filtered = q || type !== 'todas' || favs;

  return (
    <div className="mx-auto max-w-[1080px]">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-[24px] font-bold tracking-[-0.01em]">Historial</h1>
          <p className="mt-1 text-[14px] text-[#5A6372]">{history.length} textos guardados en este navegador. Ábrelos para seguir editando o pedir otra versión.</p>
        </div>
        <label className="relative w-full sm:w-[300px]">
          <Search size={15} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[#8A92A0]" aria-hidden />
          <input className="field" style={{ paddingLeft: 36 }} placeholder="Buscar en tus textos" value={q} onChange={e => setQ(e.target.value)} aria-label="Buscar en el historial" />
          {q && <button onClick={() => setQ('')} title="Borrar búsqueda" className="absolute right-2 top-1/2 -translate-y-1/2 rounded p-1 text-[#5A6372] hover:bg-[#EEF0F3]"><X size={14} aria-hidden /></button>}
        </label>
      </div>

      <div className="no-scrollbar -mx-4 mt-5 flex gap-1.5 overflow-x-auto px-4 sm:mx-0 sm:flex-wrap sm:px-0">
        <Chip on={type === 'todas'} onClick={() => setType('todas')}>Todas <span className="num opacity-70">{history.length}</span></Chip>
        {TEMPLATES.map(t => (
          <Chip key={t.id} on={type === t.id} onClick={() => setType(t.id)}>{t.short} <span className="num opacity-70">{counts[t.id] ?? 0}</span></Chip>
        ))}
        <Chip on={favs} onClick={() => setFavs(!favs)}><Star size={13} className={clsx(favs && 'fill-current')} aria-hidden /> Favoritos</Chip>
      </div>

      {list.length === 0 ? (
        <div className="mt-6 rounded-2xl border border-dashed border-[#CBD0D8] bg-white/60 px-6 py-14 text-center">
          <p className="text-[16px] font-semibold">{filtered ? 'Ningún texto coincide con tu búsqueda' : 'Aún no has generado ningún texto'}</p>
          <p className="mx-auto mt-1.5 max-w-[380px] text-[14px] text-[#5A6372]">
            {filtered ? 'Prueba con otra palabra o quita los filtros.' : 'Elige una plantilla, rellena los datos y lo que generes se guardará aquí.'}
          </p>
          <div className="mt-5">
            {filtered
              ? <Button onClick={() => { setQ(''); setType('todas'); setFavs(false); }}>Quitar filtros</Button>
              : <Button variant="primary" onClick={onNew}>Escribir mi primer texto</Button>}
          </div>
        </div>
      ) : (
        <ul className="mt-5 grid gap-3 md:grid-cols-2">
          {list.map(g => {
            const text = g.variants[g.active] ?? g.variants[0];
            return (
              <li key={g.id} className="group flex flex-col rounded-2xl border border-[#E1E4E9] bg-white transition hover:border-[#B5BCC7]">
                <button onClick={() => onOpen(g)} className="flex flex-1 flex-col justify-start rounded-t-2xl p-4 text-left sm:p-5">
                  <div className="flex w-full items-center gap-3">
                    <TemplateBadge id={g.templateId} size="sm" />
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-[14.5px] font-semibold">{titleOf(g.templateId, g.values)}</p>
                      <p className="text-[12.5px] text-[#5A6372]">{templateOf(g.templateId).name} · {g.tone} · {relTime(g.createdAt)}</p>
                    </div>
                    {g.favorite && <Star size={15} className="shrink-0 fill-[#E9A23B] text-[#E9A23B]" aria-label="Favorito" />}
                  </div>
                  <p className="prose-hoja mt-3 line-clamp-3 text-[15px] leading-[1.55] text-[#3C4452]">{text}</p>
                </button>
                <div className="flex items-center gap-1 border-t border-[#EEF0F3] px-3 py-2">
                  <span className="num flex-1 px-1 text-[12.5px] text-[#5A6372]">{g.variants.length === 1 ? '1 versión' : `${g.variants.length} versiones`}</span>
                  <Button variant="ghost" onClick={() => onFavorite(g)} title={g.favorite ? 'Quitar de favoritos' : 'Marcar como favorito'}>
                    <Star size={15} className={clsx(g.favorite && 'fill-[#E9A23B] text-[#E9A23B]')} aria-hidden />
                  </Button>
                  <Button variant="ghost" onClick={() => onCopy(text)} title="Copiar texto"><Copy size={15} aria-hidden /></Button>
                  <Button variant="ghost" onClick={() => onDelete(g)} title="Eliminar" className="hover:text-[#C2392F]"><Trash2 size={15} aria-hidden /></Button>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

function Chip({ on, onClick, children }: { on: boolean; onClick: () => void; children: ReactNode }) {
  return (
    <button onClick={onClick} aria-pressed={on}
      className={clsx('flex shrink-0 items-center gap-1.5 rounded-full border px-3 py-1.5 text-[13px] font-medium transition',
        on ? 'border-[#161B26] bg-[#161B26] text-white' : 'border-[#D5D9E0] bg-white text-[#3C4452] hover:border-[#9AA2AE]')}>
      {children}
    </button>
  );
}

import { useEffect, useState } from 'react';
import clsx from 'clsx';
import { Check, Copy, Pencil, Plus, Star } from 'lucide-react';
import type { Generation, Length, TemplateId, Tone } from '../lib/types';
import { relTime, words } from '../lib/prompts';
import { templateOf, titleOf } from '../data/templates';
import { Button, ErrorBox, RichText, TemplateBadge } from './ui';

export type Pending = { kind: 'new' | 'variant'; genId?: string; text: string; status: 'streaming' | 'error'; error?: string };

type Props = {
  templateId: TemplateId;
  draftMeta: { values: Record<string, string>; tone: Tone; length: Length };
  gen?: Generation;
  pending: Pending | null;
  recent: Generation[];
  onSelect: (i: number) => void;
  onCopy: (text: string) => void;
  onVariant: () => void;
  onSaveEdit: (index: number, text: string) => void;
  onFavorite: () => void;
  onRetry: () => void;
  onOpen: (g: Generation) => void;
};

export default function ResultPanel({ templateId, draftMeta, gen, pending, recent, onSelect, onCopy, onVariant, onSaveEdit, onFavorite, onRetry, onOpen }: Props) {
  const [editing, setEditing] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const t = templateOf(templateId);

  const isNew = pending?.kind === 'new';
  const variantPending = pending?.kind === 'variant' && gen && pending.genId === gen.id ? pending : null;
  const showPending = isNew || !!variantPending;
  const active = gen ? Math.min(gen.active, gen.variants.length - 1) : 0;
  const text = showPending ? pending!.text : gen?.variants[active] ?? '';
  const busy = pending?.status === 'streaming';

  useEffect(() => { setEditing(null); }, [gen?.id, active, pending?.kind]);
  useEffect(() => { if (!copied) return; const id = window.setTimeout(() => setCopied(false), 1800); return () => window.clearTimeout(id); }, [copied]);

  if (!gen && !isNew) return <EmptyState templateId={templateId} recent={recent} onOpen={onOpen} />;

  const meta = isNew ? draftMeta : gen!;
  const title = titleOf(templateId, meta.values);
  const count = text.length;

  return (
    <section aria-label="Resultado" className="flex flex-col rounded-2xl border border-[#E1E4E9] bg-white lg:h-[calc(100vh-150px)] lg:min-h-[520px]">
      <header className="flex items-start gap-3 border-b border-[#EEF0F3] px-4 pb-3.5 pt-4 sm:px-6">
        <TemplateBadge id={templateId} />
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-[15px] font-bold leading-tight" title={title}>{title}</h2>
          <p className="mt-1 text-[12.5px] text-[#5A6372]">
            {t.name} · {meta.tone} · {meta.length}{gen && !isNew && <> · {relTime(gen.createdAt)}</>}
          </p>
        </div>
        {gen && !isNew && (
          <button onClick={onFavorite} title={gen.favorite ? 'Quitar de favoritos' : 'Marcar como favorito'} aria-pressed={gen.favorite}
            className="rounded-lg p-2 text-[#8A92A0] hover:bg-[#F3F4F6]">
            <Star size={17} className={clsx(gen.favorite && 'fill-[#E9A23B] text-[#E9A23B]')} aria-hidden />
          </button>
        )}
      </header>

      <div className="flex flex-wrap items-center gap-2 border-b border-[#EEF0F3] px-4 py-2.5 sm:px-6">
        <div role="tablist" aria-label="Versiones" className="no-scrollbar flex min-w-0 flex-1 gap-1 overflow-x-auto">
          {isNew && <Tab on label="Versión 1" />}
          {!isNew && gen!.variants.map((_, i) => (
            <Tab key={i} on={!variantPending && i === active} label={`Versión ${i + 1}`} onClick={() => onSelect(i)} disabled={busy} />
          ))}
          {variantPending && <Tab on label={`Versión ${gen!.variants.length + 1}`} />}
        </div>
        {!showPending && editing === null && (
          <div className="flex items-center gap-1.5">
            <Button variant="ghost" onClick={onVariant} disabled={busy}><Plus size={15} aria-hidden /> Otra versión</Button>
            <Button variant="ghost" onClick={() => setEditing(text)}><Pencil size={14} aria-hidden /> Editar</Button>
            <Button onClick={() => { onCopy(text); setCopied(true); }} className={clsx(copied && 'border-[#A9D8C6] bg-[#E8F5EF] text-[#1E7F5E] hover:bg-[#E8F5EF]')}>
              {copied ? <Check size={15} aria-hidden /> : <Copy size={14} aria-hidden />} {copied ? 'Copiado' : 'Copiar'}
            </Button>
          </div>
        )}
      </div>

      <div className="scroll-thin min-h-[240px] flex-1 overflow-y-auto px-4 py-5 sm:px-8 sm:py-7">
        {editing !== null ? (
          <div className="fade-in">
            <textarea value={editing} onChange={e => setEditing(e.target.value)} aria-label="Editar texto" autoFocus
              className="field prose-hoja min-h-[300px] resize-y text-[16px] leading-[1.65]" />
            <div className="mt-3 flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setEditing(null)}>Cancelar</Button>
              <Button variant="primary" disabled={!editing.trim()} onClick={() => { onSaveEdit(active, editing.trim()); setEditing(null); }}>Guardar cambios</Button>
            </div>
          </div>
        ) : showPending && pending!.status === 'error' ? (
          <div className="space-y-4">
            {pending!.text && <RichText text={pending!.text} className="prose-hoja text-[16.5px] leading-[1.7] text-[#8A92A0]" />}
            <ErrorBox message={pending!.error ?? 'La IA no está disponible en este momento.'} onRetry={onRetry} />
          </div>
        ) : showPending && !pending!.text ? (
          <div className="space-y-3" aria-live="polite" aria-label="Escribiendo">
            <p className="text-[13px] font-medium text-[#5A6372]">Redacta está escribiendo…</p>
            {[92, 100, 84, 96, 60].map((w, i) => <div key={i} className="shimmer h-3.5" style={{ width: `${w}%` }} />)}
          </div>
        ) : (
          <article aria-live={busy ? 'polite' : undefined} className="mx-auto max-w-[620px]">
            <RichText text={text} streaming={busy && showPending} className="prose-hoja text-[16.5px] leading-[1.7] text-[#161B26]" />
          </article>
        )}
      </div>

      <footer className="flex items-center gap-4 border-t border-[#EEF0F3] px-4 py-2.5 text-[12.5px] text-[#5A6372] sm:px-6">
        <span className="num">{words(text)} palabras</span>
        <span className={clsx('num', t.charLimit && count > t.charLimit && 'font-semibold text-[#C2392F]')}>
          {count.toLocaleString('es-ES')}{t.charLimit ? ` / ${t.charLimit.toLocaleString('es-ES')}` : ''} caracteres
        </span>
        {busy && <span className="text-[#2A4BD7]">Escribiendo…</span>}
      </footer>
    </section>
  );
}

function Tab({ on, label, onClick, disabled }: { on?: boolean; label: string; onClick?: () => void; disabled?: boolean }) {
  return (
    <button role="tab" aria-selected={!!on} onClick={onClick} disabled={disabled && !on}
      className={clsx('shrink-0 rounded-lg px-2.5 py-1.5 text-[13px] font-semibold transition disabled:opacity-50',
        on ? 'bg-[#EEF0F3] text-[#161B26]' : 'text-[#5A6372] hover:text-[#161B26]')}>
      {label}
    </button>
  );
}

function EmptyState({ templateId, recent, onOpen }: { templateId: TemplateId; recent: Generation[]; onOpen: (g: Generation) => void }) {
  const t = templateOf(templateId);
  return (
    <section aria-label="Resultado" className="flex flex-col rounded-2xl border border-dashed border-[#CBD0D8] bg-white/60 p-6 sm:p-8 lg:h-[calc(100vh-150px)] lg:min-h-[520px] lg:overflow-y-auto">
      <div className="mx-auto max-w-[420px] py-6 text-center">
        <div className="mx-auto w-fit"><TemplateBadge id={templateId} /></div>
        <h2 className="mt-4 text-[18px] font-bold">Tu {t.name.toLowerCase()} aparecerá aquí</h2>
        <p className="mt-2 text-[14px] leading-relaxed text-[#5A6372]">
          Rellena los datos de la izquierda y pulsa <strong className="font-semibold text-[#161B26]">Generar texto</strong>. Verás cómo se escribe en directo,
          podrás pedir otras versiones, editarlo y copiarlo. Todo queda guardado en el historial.
        </p>
      </div>
      {recent.length > 0 && (
        <div className="mt-2 border-t border-[#E1E4E9] pt-5">
          <h3 className="text-[13px] font-semibold text-[#5A6372]">Tus últimos textos de este tipo</h3>
          <ul className="mt-3 space-y-2">
            {recent.slice(0, 3).map(g => (
              <li key={g.id}>
                <button onClick={() => onOpen(g)} className="w-full rounded-xl border border-[#E1E4E9] bg-white p-3.5 text-left transition hover:border-[#9AA2AE]">
                  <span className="block truncate text-[14px] font-semibold">{titleOf(g.templateId, g.values)}</span>
                  <span className="prose-hoja mt-1 line-clamp-2 text-[14px] leading-snug text-[#5A6372]">{g.variants[g.active] ?? g.variants[0]}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </section>
  );
}

import { useEffect, useState } from 'react';
import clsx from 'clsx';
import { Archive, Building2, Feather, MessagesSquare, PenLine, RotateCcw, X } from 'lucide-react';
import type { Business, View } from '../lib/types';
import { Button } from './ui';

const NAV: { id: View; label: string; icon: typeof PenLine }[] = [
  { id: 'escribir', label: 'Escribir', icon: PenLine },
  { id: 'historial', label: 'Historial', icon: Archive },
  { id: 'chat', label: 'Chat libre', icon: MessagesSquare },
];

type Props = { view: View; onView: (v: View) => void; historyCount: number; business: Business; onBusiness: () => void; onReset: () => void };

function Logo() {
  return (
    <div className="flex items-center gap-2.5">
      <span className="grid h-8 w-8 place-items-center rounded-[9px] bg-[#161B26] text-white"><Feather size={16} aria-hidden /></span>
      <span className="text-[17px] font-bold tracking-[-0.01em]">Redacta</span>
    </div>
  );
}

export default function Sidebar({ view, onView, historyCount, business, onBusiness, onReset }: Props) {
  return (
    <>
      {/* Escritorio */}
      <aside className="sticky top-0 hidden h-screen w-[244px] shrink-0 flex-col border-r border-[#E1E4E9] bg-white px-4 py-5 lg:flex">
        <div className="px-2"><Logo /></div>
        <nav className="mt-7 space-y-0.5" aria-label="Secciones">
          {NAV.map(n => (
