            <p className="mt-1 text-[14.5px] font-semibold leading-tight">{business.name}</p>
            <p className="mt-1 line-clamp-2 text-[12.5px] leading-snug text-[#5A6372]">{business.about} · {business.city}</p>
            <button onClick={onBusiness} className="mt-2.5 text-[13px] font-semibold text-[#2A4BD7] hover:underline">Editar perfil del negocio</button>
          </div>
          <button onClick={onReset} className="flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-[12.5px] text-[#5A6372] hover:bg-[#F3F4F6] hover:text-[#161B26]">
            <RotateCcw size={13} aria-hidden /> Restablecer ejemplo
          </button>
        </div>
      </aside>

      {/* Móvil */}
      <header className="sticky top-0 z-30 border-b border-[#E1E4E9] bg-white/95 backdrop-blur lg:hidden">
        <div className="flex items-center justify-between px-4 pt-3">
          <Logo />
          <div className="flex items-center gap-1">
            <button onClick={onBusiness} title="Perfil del negocio" className="flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-[13px] font-medium text-[#3C4452] hover:bg-[#F3F4F6]">
              <Building2 size={15} aria-hidden /> <span className="max-w-[120px] truncate">{business.name}</span>
            </button>
            <button onClick={onReset} title="Restablecer ejemplo" className="rounded-lg p-2 text-[#5A6372] hover:bg-[#F3F4F6]"><RotateCcw size={15} aria-hidden /></button>
          </div>
        </div>
        <nav className="flex gap-1 px-3 pb-2 pt-2.5" aria-label="Secciones">
          {NAV.map(n => (
            <button key={n.id} onClick={() => onView(n.id)} aria-current={view === n.id ? 'page' : undefined}
              className={clsx('flex flex-1 items-center justify-center gap-1.5 rounded-lg py-2 text-[13.5px] font-medium',
                view === n.id ? 'bg-[#EAEEFC] text-[#1E37A3]' : 'text-[#3C4452]')}>
              <n.icon size={15} aria-hidden /> {n.label}
            </button>
          ))}
        </nav>
      </header>
    </>
  );
}

export function BusinessDialog({ business, onSave, onClose }: { business: Business; onSave: (b: Business) => void; onClose: () => void }) {
  const [form, setForm] = useState(business);
  const [error, setError] = useState('');
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const save = () => {
    if (!form.name.trim()) return setError('Escribe el nombre de tu negocio.');
    onSave({ name: form.name.trim(), about: form.about.trim(), city: form.city.trim() });
  };

  const input = (key: keyof Business, label: string, ph: string) => (
    <label className="block">
      <span className="mb-1.5 block text-[13px] font-semibold">{label}</span>
      <input className={clsx('field', key === 'name' && error && 'invalid')} value={form[key]} placeholder={ph}
        onChange={e => { setForm({ ...form, [key]: e.target.value }); setError(''); }} />
    </label>
  );

  return (
    <div className="fixed inset-0 z-40 flex items-end justify-center bg-[#161B26]/40 p-0 sm:items-center sm:p-4" onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-labelledby="neg-title" onClick={e => e.stopPropagation()}
        className="fade-in w-full max-w-[440px] rounded-t-2xl bg-white p-5 shadow-xl sm:rounded-2xl sm:p-6">
        <div className="flex items-start justify-between gap-4">
          <div>
            <h2 id="neg-title" className="text-[18px] font-bold">Perfil del negocio</h2>
            <p className="mt-1 text-[13.5px] leading-snug text-[#5A6372]">Redacta lo tiene en cuenta en cada texto y en el chat.</p>
          </div>
          <button onClick={onClose} title="Cerrar" className="rounded-lg p-1.5 text-[#5A6372] hover:bg-[#F3F4F6]"><X size={18} aria-hidden /></button>
        </div>
        <div className="mt-5 space-y-4">
          {input('name', 'Nombre', 'Ej.: Café Almendro')}
          {error && <p className="-mt-2 text-[12.5px] font-medium text-[#C2392F]">{error}</p>}
          {input('about', 'A qué se dedica', 'Ej.: cafetería de especialidad con obrador propio')}
          {input('city', 'Dónde está', 'Ej.: Ruzafa, Valencia')}
        </div>
        <div className="mt-6 flex justify-end gap-2">
          <Button variant="ghost" onClick={onClose}>Cancelar</Button>
          <Button variant="primary" onClick={save}>Guardar perfil</Button>
        </div>
      </div>
    </div>
  );
}

import type { ReactNode } from 'react';
import clsx from 'clsx';
import { Camera, CircleAlert, Mail, Megaphone, MessageSquareReply, RotateCcw, Tag, type LucideIcon } from 'lucide-react';
import type { TemplateId } from '../lib/types';

export const ICONS: Record<TemplateId, LucideIcon> = {
  instagram: Camera,
  email: Mail,
  producto: Tag,
  resena: MessageSquareReply,
  oferta: Megaphone,
};

/** Color de acento suave por plantilla (fondo / icono). */
export const TINT: Record<TemplateId, string> = {
  instagram: 'bg-[#F3E8F7] text-[#7A2E8E]',
  email: 'bg-[#E6EEFB] text-[#2348B8]',
  producto: 'bg-[#E4F3EC] text-[#1E7F5E]',
  resena: 'bg-[#FCEFD9] text-[#8A5A08]',
  oferta: 'bg-[#FBE7E4] text-[#A8352B]',
};

export function TemplateBadge({ id, size = 'md' }: { id: TemplateId; size?: 'sm' | 'md' }) {
  const Icon = ICONS[id];
  return (
    <span className={clsx('inline-flex shrink-0 items-center justify-center rounded-lg', TINT[id], size === 'sm' ? 'h-7 w-7' : 'h-9 w-9')}>
      <Icon size={size === 'sm' ? 14 : 17} strokeWidth={2} aria-hidden />
    </span>
  );
}

type BtnProps = { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'ghost' | 'soft'; disabled?: boolean; className?: string; title?: string; type?: 'button' | 'submit' };
export function Button({ children, onClick, variant = 'soft', disabled, className, title, type = 'button' }: BtnProps) {
  return (
    <button type={type} onClick={onClick} disabled={disabled} title={title} aria-label={title}
      className={clsx('inline-flex items-center justify-center gap-1.5 whitespace-nowrap rounded-[10px] text-[13.5px] font-semibold transition disabled:cursor-not-allowed disabled:opacity-50',
        variant === 'primary' && 'bg-[#2A4BD7] px-4 py-2.5 text-white shadow-[0_1px_0_rgba(0,0,0,.08)] hover:bg-[#2340BC] active:bg-[#1E37A3]',
        variant === 'soft' && 'border border-[#D5D9E0] bg-white px-3 py-2 text-[#161B26] hover:border-[#BCC2CC] hover:bg-[#F7F8FA]',
        variant === 'ghost' && 'px-2.5 py-2 text-[#5A6372] hover:bg-[#EEF0F3] hover:text-[#161B26]',
        className)}>
      {children}
    </button>
  );
}

/** Pinta texto con párrafos, listas, **negritas** y #hashtags. */
export function RichText({ text, streaming, className }: { text: string; streaming?: boolean; className?: string }) {
  const blocks = text.split(/\n{2,}/);
  return (
    <div className={clsx('space-y-3.5', className)}>
      {blocks.map((block, bi) => {
        const lines = block.split('\n').filter(l => l.trim() !== '');
        const last = bi === blocks.length - 1;
        const isUl = lines.length > 0 && lines.every(l => /^\s*[-•*]\s+/.test(l));
        const isOl = lines.length > 0 && lines.every(l => /^\s*\d+[.)]\s+/.test(l));
        if (isUl || isOl) {
          const Tag = isOl ? 'ol' : 'ul';
          return (
            <Tag key={bi} className={clsx('space-y-1.5 pl-5', isOl ? 'list-decimal' : 'list-disc', 'marker:text-[#8A92A0]')}>
              {lines.map((l, li) => (
                <li key={li} className={clsx(streaming && last && li === lines.length - 1 && 'caret')}>
                  {inline(l.replace(/^\s*([-•*]|\d+[.)])\s+/, ''))}
                </li>
              ))}
            </Tag>
          );
        }
        return (
          <p key={bi} className={clsx(streaming && last && 'caret')}>
            {lines.map((l, li) => (
              <span key={li}>{li > 0 && <br />}{inline(l.replace(/^#{1,4}\s+/, ''))}</span>
            ))}
          </p>
        );
      })}
    </div>
  );
}

function inline(s: string): ReactNode[] {
  return s.split(/(\*\*[^*]+\*\*|#[\p{L}\p{N}_]+)/u).map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**') && part.length > 4) return <strong key={i} className="font-semibold">{part.slice(2, -2)}</strong>;
    if (/^#[\p{L}\p{N}_]+$/u.test(part)) return <span key={i} className="text-[#2A4BD7]">{part}</span>;
    return <span key={i}>{part}</span>;
  });
}

export function ErrorBox({ message, onRetry }: { message: string; onRetry: () => void }) {
  return (
    <div role="alert" className="fade-in flex items-start gap-3 rounded-xl border border-[#F0C9C5] bg-[#FDF3F2] p-4 text-[#7A231C]">
      <CircleAlert size={18} className="mt-0.5 shrink-0 text-[#C2392F]" aria-hidden />
      <div className="min-w-0 flex-1">
        <p className="text-[14px] font-semibold">No hemos podido terminar el texto</p>
        <p className="mt-0.5 text-[13px] leading-snug text-[#8E3A33]">{message} Tus datos siguen aquí; puedes intentarlo de nuevo.</p>
      </div>
      <Button onClick={onRetry} className="shrink-0"><RotateCcw size={14} aria-hidden /> Reintentar</Button>
    </div>
  );
}

export type ToastData = { message: string; action?: { label: string; run: () => void } } | null;

export function Toast({ toast, onClose }: { toast: ToastData; onClose: () => void }) {
  if (!toast) return null;
  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-5 z-50 flex justify-center px-4 sm:bottom-6">
      <div role="status" className="fade-in pointer-events-auto flex max-w-[460px] items-center gap-3 rounded-xl bg-[#161B26] py-2.5 pl-4 pr-2 text-[13.5px] text-white shadow-lg">
        <span className="min-w-0 flex-1">{toast.message}</span>
        {toast.action && (
          <button onClick={() => { toast.action!.run(); onClose(); }} className="rounded-lg px-2.5 py-1 font-semibold text-[#A9B8FF] hover:bg-white/10">
            {toast.action.label}
          </button>
        )}
      </div>
    </div>
  );
}

