export const templateOf = (id: TemplateId): Template => TEMPLATES.find(t => t.id === id) ?? TEMPLATES[0];

export const emptyValues = (): Record<TemplateId, Record<string, string>> =>
  Object.fromEntries(TEMPLATES.map(t => [t.id, Object.fromEntries(t.fields.filter(f => f.type === 'select').map(f => [f.key, f.options![0]]))])) as Record<TemplateId, Record<string, string>>;

/** Título corto de un texto generado a partir de su primer campo. */
export const titleOf = (templateId: TemplateId, values: Record<string, string>): string => {
  const t = templateOf(templateId);
  const first = values[t.fields[0].key]?.trim() || t.name;
  return first.length > 72 ? first.slice(0, 70).trimEnd() + '…' : first;
};

