  const datos = t.fields
    .filter(f => r.values[f.key]?.trim())
    .map(f => `- ${f.label}: ${r.values[f.key].trim()}`)
    .join('\n');
  const extra: Record<TemplateId, string> = {
    instagram: 'Empieza con una primera línea que enganche. Usa como mucho 2 emojis. Los hashtags, si se piden, van al final en una sola línea.',
    email: 'Incluye una primera línea «Asunto: …», saludo, cuerpo en párrafos cortos y despedida con la firma.',
    producto: 'Empieza por el nombre del producto. Describe sensaciones y usos concretos. Termina con el precio si se indica.',
    resena: 'Agradece, responde a lo concreto de la reseña, reconoce lo que haya que mejorar sin excusas y firma en nombre del negocio.',
    oferta: 'Que la oferta se entienda en la primera línea. Incluye fechas y condiciones de forma clara.',
  };
  let p = `Escribe: ${t.name.toLowerCase()}.\nTono: ${TONE_HINT[r.tone]}.\nExtensión: unas ${target} palabras.\n${extra[r.templateId]}\n\nDatos:\n${datos}`;
  if (previous.length) p += `\n\nYa existe esta versión; escribe una alternativa claramente distinta en enfoque y en la primera frase:\n"""${previous[previous.length - 1]}"""`;
  return p;
}

export const words = (s: string) => (s.trim() ? s.trim().split(/\s+/).length : 0);

export function relTime(ts: number): string {
  const diff = Date.now() - ts;
  const m = Math.round(diff / 60000);
  if (m < 1) return 'ahora mismo';
  if (m < 60) return `hace ${m} min`;
  const h = Math.round(m / 60);
  if (h < 24) return `hace ${h} h`;
  const d = Math.round(h / 24);
  if (d === 1) return 'ayer';
  if (d < 7) return `hace ${d} días`;
  return new Date(ts).toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });
}

export async function copyText(text: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text);
    return;
  } catch { /* plan B */ }
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  try { document.execCommand('copy'); } catch { /* sin portapapeles */ }
  ta.remove();
}

import { useCallback, useEffect, useState } from 'react';
import type { AppData, Business, ChatMessage, Draft, Generation } from './types';
import { buildSeed } from '../data/seed';

const KEY = 'redacta:datos:v1';

function load(): AppData {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const d = JSON.parse(raw) as AppData;
      if (Array.isArray(d.history) && Array.isArray(d.chat) && d.draft && d.business) return d;
    }
  } catch { /* sin almacenamiento */ }
  return buildSeed();
}

export const uid = (p: string) => `${p}-${Math.random().toString(36).slice(2, 9)}`;

export function useStore() {
  const [data, setData] = useState<AppData>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch { /* sin almacenamiento */ }
  }, [data]);

  const setDraft = useCallback((patch: Partial<Draft>) => setData(d => ({ ...d, draft: { ...d.draft, ...patch } })), []);

  const setField = useCallback((key: string, value: string) => setData(d => {
    const t = d.draft.templateId;
    return { ...d, draft: { ...d.draft, values: { ...d.draft.values, [t]: { ...d.draft.values[t], [key]: value } } } };
  }), []);

  const addGeneration = useCallback((g: Generation) => setData(d => ({ ...d, history: [g, ...d.history], activeId: g.id })), []);

  const updateGeneration = useCallback((id: string, patch: Partial<Generation>) =>
    setData(d => ({ ...d, history: d.history.map(g => (g.id === id ? { ...g, ...patch } : g)) })), []);

  const addVariant = useCallback((id: string, text: string) => setData(d => ({
    ...d,
    history: d.history.map(g => (g.id === id ? { ...g, variants: [...g.variants, text], active: g.variants.length } : g)),
  })), []);

  const editVariant = useCallback((id: string, index: number, text: string) => setData(d => ({
    ...d,
    history: d.history.map(g => (g.id === id ? { ...g, variants: g.variants.map((v, i) => (i === index ? text : v)) } : g)),
  })), []);

  const removeGeneration = useCallback((id: string) =>
    setData(d => ({ ...d, history: d.history.filter(g => g.id !== id), activeId: d.activeId === id ? null : d.activeId })), []);

  /** Abre un texto del historial en el editor, con sus campos. */
  const openGeneration = useCallback((g: Generation) => setData(d => ({
    ...d,
    activeId: g.id,
    draft: { ...d.draft, templateId: g.templateId, tone: g.tone, length: g.length, values: { ...d.draft.values, [g.templateId]: { ...g.values } } },
  })), []);

  const setBusiness = useCallback((business: Business) => setData(d => ({ ...d, business })), []);
  const addMessage = useCallback((m: ChatMessage) => setData(d => ({ ...d, chat: [...d.chat, m] })), []);
  const clearChat = useCallback(() => setData(d => ({ ...d, chat: [] })), []);
  const replace = useCallback((next: AppData) => setData(next), []);
  const reset = useCallback(() => setData(buildSeed()), []);

  return { data, setDraft, setField, addGeneration, updateGeneration, addVariant, editVariant, removeGeneration, openGeneration, setBusiness, addMessage, clearChat, replace, reset };
}

export type Store = ReturnType<typeof useStore>;

export type TemplateId = 'instagram' | 'email' | 'producto' | 'resena' | 'oferta';
